public List<string> AllocateOrder(string ticketId, string sku, int qty, int shipDay, bool allowBackorder) {
    // 1. Idempotent check
    if (ProcessedTickets.Contains(ticketId)) {
        return SavedTickets[ticketId];
    }

    // 2. Filter eligible lots
    var eligible = Lots.Where(l => l.Sku == sku && !l.Quarantined && l.Qty > 0 && l.ExpiryDay >= shipDay + MinShelfLifeDays)
                       .OrderBy(l => l.ExpiryDay)
                       .ThenBy(l => l.Id)
                       .ToList();

    int totalEligibleQty = eligible.Sum(l => l.Qty);

    // 4. Insufficient stock check
    if (totalEligibleQty < qty && !allowBackorder) {
        return null;
    }

    List<string> ticketLines = new List<string>();
    int remainingQty = qty;

    foreach (var lot in eligible) {
        if (remainingQty <= 0) break;
        int pickQty = Math.Min(lot.Qty, remainingQty);
        lot.Qty -= pickQty;
        remainingQty -= pickQty;
        ticketLines.Add($"PICK:{lot.Id}:{pickQty}");
        AuditLog.Add($"PICK:{lot.Id}:{pickQty}");
    }

    // Remove depleted lots
    Lots.RemoveAll(l => l.Qty == 0);

    // 5. Backorder handling
    if (remainingQty > 0) {
        ticketLines.Add($"BACKORDER:{sku}:{remainingQty}");
        AuditLog.Add($"BACKORDER:{sku}:{remainingQty}");
    }

    // 6. Save ticket
    SavedTickets[ticketId] = ticketLines;
    ProcessedTickets.Add(ticketId);

    return ticketLines;
}

