class HotelSystem
{
    static Dictionary<string, int> inventory = new Dictionary<string, int>(); // category -> rooms
    static Dictionary<string, int> rates = new Dictionary<string, int>();     // category -> nightly rate
    static string[] upgradeOrder;  // categories from lowest to highest
    static int overbookPct;        // e.g. 10 means allow 10% overbooking
    static Dictionary<string, string> reservations = new Dictionary<string, string>(); // resId -> category
    static Dictionary<string, int> resDays = new Dictionary<string, int>();            // resId -> nights
    static List<string> auditLog = new List<string>();
