        auditLog.Clear(); revenue = 0; upgradeOrder = order; overbookPct = obPct;
    }

    static void AddCategory(string cat, int rooms, int rate)
    {
        inventory[cat] = rooms; rates[cat] = rate;
    }

    static int EffectiveCapacity(string cat)
    {
        return inventory[cat] + inventory[cat] * overbookPct / 100;
    }

