    //  3. Refund = total - fee. Subtract refund from revenue (revenue can go negative).
    //  4. Remove reservation, audit "CANCEL:resId:fee:refund".
    //  5. Return "CANCELLED:fee:refund".
    static string Cancel(string resId, int daysBefore)
    {
        if (!reservations.ContainsKey(resId)) return "NOT_FOUND";
