static int ComputeTax(int gross)
{
    int adjustedExemption = exemptionAmount;
    if (gross > phaseOutStart)
    {
        int excess = gross - phaseOutStart;
        int reductions = excess / phaseOutStep;
        int reductionPct = reductions * 2;
