        if (adjustedExemption < 0) adjustedExemption = 0;
    }

    int taxableIncome = gross - stdDeduction - adjustedExemption;
    if (taxableIncome < 0) taxableIncome = 0;

    int totalTax = 0;
    int prevLimit = 0;
    foreach (var bracket in brackets)
    {
        int upperLimit = bracket[0];
        int rate = bracket[1];
        int sliceEnd = Math.Min(taxableIncome, upperLimit);
        if (sliceEnd > prevLimit)
        {
            int slice = sliceEnd - prevLimit;
            totalTax += slice * rate / 100;
        }
        prevLimit = upperLimit;
        if (taxableIncome <= prevLimit) break;
    }

    calcLog.Add($"TAX:{gross}:{taxableIncome}:{adjustedExemption}:{totalTax}");
