class InvoiceProcessor
{
    static Dictionary<string, int> invoiceAmounts = new Dictionary<string, int>(); // invoiceId -> original amount
    static Dictionary<string, int> invoiceDueDays = new Dictionary<string, int>();  // invoiceId -> due day
    static Dictionary<string, int> balances = new Dictionary<string, int>();         // invoiceId -> remaining
    static int creditPool;  // shared credit memo pool
    static int earlyDiscountPct;  // discount if paid earlyDays before due
    static int earlyDays;
    static int latePenaltyPct;    // penalty per late day (applied to original amount)
    static int maxPenaltyPct;     // cap on total penalty
    static List<string> payLog = new List<string>();
    static HashSet<string> fullyPaid = new HashSet<string>();

    static void Reset(int credit, int earlyPct, int eDays, int latePct, int maxPct)
    {
        invoiceAmounts.Clear(); invoiceDueDays.Clear(); balances.Clear();
        payLog.Clear(); fullyPaid.Clear();
        creditPool = credit; earlyDiscountPct = earlyPct; earlyDays = eDays;
        latePenaltyPct = latePct; maxPenaltyPct = maxPct;
    }

    static void AddInvoice(string id, int amount, int dueDay)
    {
        invoiceAmounts[id] = amount; invoiceDueDays[id] = dueDay;
        balances[id] = amount;
    }

    // Process a payment for an invoice.
    // Rules:
    //  1. If invoice not found or already fully paid, return "INVALID".
    //  2. Compute adjustedBalance:
    //     - If payDay <= dueDay - earlyDays: apply earlyDiscountPct to remaining balance. adjustedBalance = balance - balance*earlyDiscountPct/100.
    //     - If payDay > dueDay: lateDays = payDay - dueDay. penalty = min(lateDays*latePenaltyPct, maxPenaltyPct) * invoiceAmounts[id] / 100.
    //       adjustedBalance = balance + penalty.
    //     - Otherwise: adjustedBalance = balance (no adjustment).
    //  3. Apply credit: creditUsed = min(creditPool, adjustedBalance). Reduce creditPool. Reduce adjustedBalance.
    //  4. cashNeeded = adjustedBalance (after credit). If cashAmount < cashNeeded, return "UNDERPAYMENT" with no mutation.
    //  5. On success: set balance to 0, add to fullyPaid, log "PAY:id:creditUsed:cashUsed:penalty_or_discount".
    //  6. Return "PAID:creditUsed:cashUsed".
    static string Pay(string invoiceId, int payDay, int cashAmount)
    {

golden_completion:
