int balance = balances[invoiceId];
int dueDay = invoiceDueDays[invoiceId];
int original = invoiceAmounts[invoiceId];
int adjusted = balance;
int adj = 0;
if (payDay <= dueDay - earlyDays)
{
    adj = balance * earlyDiscountPct / 100;
    adjusted = balance - adj;
}
else if (payDay > dueDay)
{
    int lateDays = payDay - dueDay;
    int penPct = Math.Min(lateDays * latePenaltyPct, maxPenaltyPct);
    adj = original * penPct / 100;
    adjusted = balance + adj;
}
int creditUsed = Math.Min(creditPool, adjusted);
int afterCredit = adjusted - creditUsed;
if (cashAmount < afterCredit) return "UNDERPAYMENT";
creditPool -= creditUsed;
balances[invoiceId] = 0;
fullyPaid.Add(invoiceId);
payLog.Add("PAY:" + invoiceId + ":" + creditUsed + ":" + afterCredit + ":" + adj);
return "PAID:" + creditUsed + ":" + afterCredit;

suffix:
    }

