class Program
{
    static Dictionary<string, int> vehicleMileage = new Dictionary<string, int>();
    static Dictionary<string, int> lastServiceDay = new Dictionary<string, int>();
    static Dictionary<string, int> lastServiceMileage = new Dictionary<string, int>();
    static Dictionary<string, int> missedServices = new Dictionary<string, int>();
    static Dictionary<string, int> partsInventory = new Dictionary<string, int>();
    static List<string> serviceLog = new List<string>();

