using System;
using System.Collections.Generic;
using System.Linq;

class Program
{
    static Dictionary<string, int> patronCheckouts = new Dictionary<string, int>();
    static Dictionary<string, decimal> patronFines = new Dictionary<string, decimal>();
    static Dictionary<string, string> itemBorrower = new Dictionary<string, string>();
    static Dictionary<string, int> itemDueDay = new Dictionary<string, int>();
    static Dictionary<string, int> itemRenewals = new Dictionary<string, int>();
    static Dictionary<string, Queue<string>> holdsQueue = new Dictionary<string, Queue<string>>();
    static List<string> circLog = new List<string>();

    static int maxCheckouts = 5;
    static int loanPeriod = 14;
    static int maxRenewals = 2;
    static decimal finePerDay = 0.25m;

    static void Reset()
    {
        patronCheckouts.Clear(); patronFines.Clear(); itemBorrower.Clear();
        itemDueDay.Clear(); itemRenewals.Clear(); holdsQueue.Clear(); circLog.Clear();
    }

    static void RegisterPatron(string pid) { patronCheckouts[pid] = 0; patronFines[pid] = 0m; }

    static string CheckoutItem(string patronId, string itemId, int day)
