if (patronCheckouts[patronId] >= maxCheckouts) return "CHECKOUT_LIMIT";
if (itemBorrower.ContainsKey(itemId))
{
    if (!holdsQueue.ContainsKey(itemId)) holdsQueue[itemId] = new Queue<string>();
    if (!holdsQueue[itemId].Contains(patronId)) { holdsQueue[itemId].Enqueue(patronId); circLog.Add("HOLD:" + patronId + ":" + itemId + ":pos=" + holdsQueue[itemId].Count); }
    return "ON_HOLD:" + holdsQueue[itemId].Count;
}
bool hasHold = holdsQueue.ContainsKey(itemId) && holdsQueue[itemId].Count > 0;
if (hasHold && holdsQueue[itemId].Peek() != patronId) return "HELD_FOR_OTHER";
if (hasHold && holdsQueue[itemId].Peek() == patronId) holdsQueue[itemId].Dequeue();
itemBorrower[itemId] = patronId; itemDueDay[itemId] = day + loanPeriod; itemRenewals[itemId] = 0;
patronCheckouts[patronId]++;
circLog.Add("CHECKOUT:" + patronId + ":" + itemId + ":due=" + (day + loanPeriod));
return "CHECKED_OUT:due=" + (day + loanPeriod);

suffix:
    }

    static string ReturnItem(string itemId, int day)
    {
        if (!itemBorrower.ContainsKey(itemId)) return "NOT_CHECKED_OUT";
        string patron = itemBorrower[itemId];
        int overdueDays = Math.Max(0, day - itemDueDay[itemId]);
        decimal fine = overdueDays * finePerDay;
        patronFines[patron] += fine;
        patronCheckouts[patron]--;
        itemBorrower.Remove(itemId);
        itemDueDay.Remove(itemId);
        itemRenewals.Remove(itemId);
        circLog.Add("RETURN:" + patron + ":" + itemId + ":fine=" + fine);
        if (holdsQueue.ContainsKey(itemId) && holdsQueue[itemId].Count > 0)
        {
            string next = holdsQueue[itemId].Peek();
            circLog.Add("HOLD_AVAILABLE:" + next + ":" + itemId);
            return "RETURNED:HOLD_NOTIFY=" + next + ":fine=" + fine;
        }
        return "RETURNED:fine=" + fine;
    }

